script:
frappe.ui.form.on('JobEstimation', {
    refresh: function(frm) {
        // Calculate estimated end date on form load
        calculate_estimated_end_date(frm);
        
        // Add manual button for testing
        frm.add_custom_button(__('Calculate End Date'), function() {
            calculate_estimated_end_date(frm);
        });
    },
    
    estimated_start_date: function(frm) {
        // Recalculate when start date changes
        calculate_estimated_end_date(frm);
        update_operation_dates(frm);
    },
    
    siteinspection: function (frm) {
        if (frm.doc.siteinspection) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'SiteInspection',
                    name: frm.doc.siteinspection
                },
                callback: function (r) {
                    if (r.message && r.message.site_dimensions) {
                        // Populate Site Dimensions
                        frm.clear_table('site_dimensions');
                        let all_images = [];
                        let entitySet = new Set();
                        frm.clear_table('boq');

                        r.message.site_dimensions.forEach((row) => {
                            let new_row = frm.add_child('site_dimensions');
                            new_row.no = row.no;
                            new_row.floor = row.floor;
                            new_row.room = row.room;
                            new_row.entity = row.entity;
                            new_row.area_name = row.area_name;
                            new_row.dimensionsunits = row.dimensionsunits;
                            new_row.media = row.media;

                            if (row.media) {
                                new_row.media_preview = `<img src="${row.media}" style="width: 60px; height: 60px; object-fit: cover; border-radius: 4px;">`;
                                all_images.push({
                                    image: row.media,
                                    caption: `${row.floor || ''} - ${row.room || ''} - ${row.area_name || ''}`
                                });
                            }

                            // Populate BOQ table with unique entities
                            if (row.entity && !entitySet.has(row.entity)) {
                                let boq_row = frm.add_child('boq');
                                boq_row.entity = row.entity;
                                boq_row.description = `${row.floor || ''} - ${row.room || ''} - ${row.area_name || ''}`;
                                entitySet.add(row.entity);
                            }
                        });

                        frm.refresh_field('site_dimensions');
                        frm.refresh_field('boq');
                        show_all_images(frm, all_images);

                        frm.fields_dict.site_dimensions.grid.cannot_add_rows = true;
                        frm.fields_dict.site_dimensions.grid.cannot_delete_rows = true;

                        frappe.show_alert({ message: 'Site Dimensions loaded!', indicator: 'green' });
                    } else {
                        frappe.show_alert({ message: 'No Site Dimensions found!', indicator: 'yellow' });
                    }
                }
            });
        } else {
            frm.clear_table('site_dimensions');
            frm.clear_table('boq');
            frm.refresh_field('site_dimensions');
            frm.refresh_field('boq');
            if ($('#all-images-container').length) {
                $('#all-images-container').html('');
            }
        }
    }
});

// When BOM is selected, fetch total_cost from BOM and set it to complete_cost in BOQ
frappe.ui.form.on('BOQ Item', {
    bom: function (frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.bom) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'BOM',
                    name: row.bom
                },
                callback: function (r) {
                    if (r.message) {
                        let bom_cost = r.message.total_cost || 0;
                        frappe.model.set_value(cdt, cdn, 'complete_cost', bom_cost);
                        update_total_estimation(frm);
                    }
                }
            });
        } else {
            frappe.model.set_value(cdt, cdn, 'complete_cost', 0);
            update_total_estimation(frm);
        }
    },

    complete_cost: function (frm) {
        update_total_estimation(frm);
    }
});

// Script for Tentative Schedule child table
frappe.ui.form.on('Tentative Schedule', {
    time: function(frm, cdt, cdn) {
        calculate_estimated_end_date(frm);
        update_operation_dates(frm);
    },
    
    tentative_schedule_for_execution_add: function(frm) {
        set_next_operation_date(frm);
        calculate_estimated_end_date(frm);
    },
    
    tentative_schedule_for_execution_remove: function(frm) {
        calculate_estimated_end_date(frm);
        update_operation_dates(frm);
    }
});

// Add up all complete_cost values
function update_total_estimation(frm) {
    let total = 0;
    (frm.doc.boq || []).forEach(row => {
        total += flt(row.complete_cost);
    });
    frm.set_value('total_estimation_amount', total);
    frm.refresh_field('total_estimation_amount');
}

// Calculate estimated end date based on total time from child table
function calculate_estimated_end_date(frm) {
    console.log('🔍 DEBUG: calculate_estimated_end_date called');
    
    let total_time = 0;
    let start_date = frm.doc.estimated_start_date;
    
    console.log('📅 Start Date:', start_date);
    console.log('📋 Child Table Data:', frm.doc.tentative_schedule_for_execution);
    
    // Check if start date exists
    if (!start_date) {
        console.log('❌ No start date found');
        frm.set_value('estimated_end_date', '');
        return;
    }
    
    // Sum all time values from child table
    if (frm.doc.tentative_schedule_for_execution && frm.doc.tentative_schedule_for_execution.length > 0) {
        frm.doc.tentative_schedule_for_execution.forEach(function(row, index) {
            console.log(`Row ${index}:`, row);
            if (row.time && !isNaN(parseFloat(row.time))) {
                total_time += parseFloat(row.time);
                console.log(`Added ${row.time}, Total: ${total_time}`);
            }
        });
    } else {
        console.log('❌ No tentative_schedule_for_execution data found');
    }
    
    console.log('⏰ Total Time:', total_time);
    
    // Calculate days (divide by 8 hours per day)
    let total_days = Math.ceil(total_time / 8);
    console.log('📆 Total Days:', total_days);
    
    // Add days to start date
    if (total_days > 0) {
        let start_date_obj = new Date(start_date);
        
        // Check if date is valid
        if (isNaN(start_date_obj.getTime())) {
            console.log('❌ Invalid start date');
            return;
        }
        
        // Add calendar days
        start_date_obj.setDate(start_date_obj.getDate() + total_days);
        
        // Format date as YYYY-MM-DD
        let end_date = start_date_obj.getFullYear() + '-' + 
                      String(start_date_obj.getMonth() + 1).padStart(2, '0') + '-' + 
                      String(start_date_obj.getDate()).padStart(2, '0');
        
        console.log('📅 Calculated End Date:', end_date);
        frm.set_value('estimated_end_date', end_date);
        frappe.show_alert({message: `End date calculated: ${end_date}`, indicator: 'green'});
    } else {
        frm.set_value('estimated_end_date', '');
        console.log('❌ No time data to calculate');
    }
}

// Set next operation date when new row is added
function set_next_operation_date(frm) {
    let rows = frm.doc.tentative_schedule_for_execution || [];
    
    if (rows.length > 0) {
        let last_row = rows[rows.length - 1];
        let previous_row = rows[rows.length - 2];
        
        if (rows.length === 1) {
            // First operation gets estimated_start_date
            if (frm.doc.estimated_start_date) {
                frappe.model.set_value(last_row.doctype, last_row.name, 'date', frm.doc.estimated_start_date);
            }
        } else if (previous_row && previous_row.date && previous_row.time) {
            // Calculate end date of previous operation
            let prev_start = new Date(previous_row.date);
            let prev_hours = parseFloat(previous_row.time) || 0;
            let prev_days = Math.ceil(prev_hours / 8);
            
            // Check if previous date is valid
            if (!isNaN(prev_start.getTime())) {
                // Add days to get end date of previous operation
                prev_start.setDate(prev_start.getDate() + prev_days);
                
                // Format date
                let next_date = prev_start.getFullYear() + '-' + 
                              String(prev_start.getMonth() + 1).padStart(2, '0') + '-' + 
                              String(prev_start.getDate()).padStart(2, '0');
                
                // Set as start date for current operation
                frappe.model.set_value(last_row.doctype, last_row.name, 'date', next_date);
            }
        }
    }
}

// Update all operation dates when time changes
function update_operation_dates(frm) {
    let rows = frm.doc.tentative_schedule_for_execution || [];
    
    rows.forEach((row, index) => {
        if (index === 0) {
            // First operation always gets estimated_start_date
            if (frm.doc.estimated_start_date) {
                frappe.model.set_value(row.doctype, row.name, 'date', frm.doc.estimated_start_date);
            }
        } else {
            // Calculate based on previous operation
            let previous_row = rows[index - 1];
            if (previous_row && previous_row.date && previous_row.time) {
                let prev_start = new Date(previous_row.date);
                let prev_hours = parseFloat(previous_row.time) || 0;
                let prev_days = Math.ceil(prev_hours / 8);
                
                // Check if previous date is valid
                if (!isNaN(prev_start.getTime())) {
                    prev_start.setDate(prev_start.getDate() + prev_days);
                    
                    let next_date = prev_start.getFullYear() + '-' + 
                                  String(prev_start.getMonth() + 1).padStart(2, '0') + '-' + 
                                  String(prev_start.getDate()).padStart(2, '0');
                    
                    frappe.model.set_value(row.doctype, row.name, 'date', next_date);
                }
            }
        }
    });
}

// Show site images
function show_all_images(frm, images) {
    let html = '<div style="display: flex; flex-wrap: wrap; gap: 15px; margin-top: 10px;">';
    images.forEach(function (img) {
        html += `
            <div style="border: 1px solid #ddd; border-radius: 8px; padding: 10px; text-align: center; width: 200px;">
                <img src="${img.image}" 
                     style="width: 180px; height: 180px; object-fit: cover; border-radius: 4px; cursor: pointer;"
                     onclick="window.open('${img.image}', '_blank')">
                <div style="margin-top: 8px; font-size: 12px; color: #666;">${img.caption}</div>
            </div>
        `;
    });
    html += '</div>';
    
    // Create container if it doesn't exist
    if ($('#all-images-container').length === 0) {
        $('body').append('<div id="all-images-container"></div>');
    }
    $('#all-images-container').html(html);
}

frappe.ui.form.on('JobEstimation', {
    is_different_from_this: function(frm) {
        if (frm.doc.is_different_from_this) {
            frm.set_df_property('estimated_end_date', 'hidden', 1);
            frm.set_df_property('manual_end_date', 'hidden', 0);
        } else {
            frm.set_df_property('estimated_end_date', 'hidden', 0);
            frm.set_df_property('manual_end_date', 'hidden', 1);
        }
    },

    refresh: function(frm) {
        // Make sure visibility is correct on form load
        frm.trigger('is_different_from_this');
    }
});

// Main DocType (JobEstimation) events
frappe.ui.form.on('JobEstimation', {
    refresh: function(frm) {
        frm.set_query('employee', 'tentative_schedule_for_execution', function(doc, cdt, cdn) {
            let child_doc = locals[cdt][cdn];
            
            if (child_doc && child_doc.operation) {
                return {
                    filters: {
                        'operation': child_doc.operation
                    }
                };
            }
            return {};
        });
        // Check employee availability before allowing selection
    }
});

// Child Table (execution_work) events
frappe.ui.form.on('execution_work', {
    operation: function(frm, cdt, cdn) {
        let child_doc = locals[cdt][cdn];
        
        // Clear employee if operation changes
        if (child_doc.employee) {
            frappe.model.set_value(cdt, cdn, 'employee', '');
        }
        
        // Refresh the field
        frm.refresh_field('tentative_schedule_for_execution');
    }
});

