// Script Name: Job Estimation - Manual Booking Button
// Document Type: Job Estimation
// Script Type: Form Script

frappe.ui.form.on('JobEstimation', {
    refresh: function(frm) {
        // Add custom button to manually create Booking Employee records
        if (frm.doc.docstatus === 1 && frm.doc.job_execution && frm.doc.job_execution.length > 0) {
            frm.add_custom_button(__('Create Booking Records'), function() {
                frappe.call({
                    method: 'frappe.client.submit_doc',
                    args: {
                        doc: frm.doc
                    },
                    callback: function(r) {
                        if (r.message) {
                            frappe.msgprint(__('Booking Employee records creation triggered'));
                            frm.refresh();
                        }
                    }
                });
            }, __('Actions'));
        }
    },
    
    // Validate before submit
    before_submit: function(frm) {
        if (frm.doc.job_execution && frm.doc.job_execution.length > 0) {
            let missing_fields = [];
            
            frm.doc.job_execution.forEach(function(row, index) {
                if (!row.employee) {
                    missing_fields.push(`Row ${index + 1}: Employee is required`);
                }
                if (!row.date) {
                    missing_fields.push(`Row ${index + 1}: Date is required`);
                }
            });
            
            if (missing_fields.length > 0) {
                frappe.msgprint({
                    title: __('Missing Required Fields'),
                    message: missing_fields.join('<br>'),
                    indicator: 'red'
                });
                frappe.validated = false;
            }
        }
    }
});
